import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
  Img,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadRoboto = makeLoadFont('Roboto');

// Load Google font at module level to guarantee it's ready before frame 0
const { fontFamily: robotoFamily } = loadRoboto();

// Single inline schema definition


export type GoogleReviewOverlayProps = Record<string, any>;

const GoogleReviewOverlay: React.FC<GoogleReviewOverlayProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 8,
  reviewerName = "Sarah Jenkins",
  reviewText = "Incredible experience from start to finish. Malloy Studio transformed our vision into reality with stunning attention to detail. Five stars all the way!",
  rating = 5,
  avatarImg = "https://images.unsplash.com/photo-1494790108377-be9c29b29330?q=80&w=256&h=256&fit=crop",
  cardBackgroundColor = "#ffffff",
  textColor = "#202124",
  subTextColor = "#5f6368",
  starColor = "#FBBC05",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Background transparency logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timings
  const introDuration = 30;
  const outroStartFrame = Math.max(0, fps * durationInSeconds - 30);

  // Animations - Intro
  const cardEntrance = spring({
    fps,
    frame,
    config: { damping: 14, stiffness: 100 },
  });

  // Animations - Outro
  const cardExit = spring({
    fps,
    frame: frame - outroStartFrame,
    config: { damping: 14, stiffness: 100 },
  });

  // Derived values for layout
  const cardScale = interpolate(cardEntrance, [0, 1], [0.8, 1]) - interpolate(cardExit, [0, 1], [0, 0.2]);
  const cardOpacity = interpolate(cardEntrance, [0, 1], [0, 1]) - interpolate(cardExit, [0, 1], [0, 1]);
  const cardTranslateY = 
    interpolate(cardEntrance, [0, 1], [150, 0]) + 
    interpolate(cardExit, [0, 1], [0, 150]);

  // Design constants
  const cardWidth = Math.min(width * 0.7, 1100);
  const cardPadding = 48;
  const avatarSize = 120;

  // Google Brand Colors for the top bar
  const googleBlue = "#4285F4";
  const googleRed = "#EA4335";
  const googleYellow = "#FBBC05";
  const googleGreen = "#34A853";

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: robotoFamily,
        justifyContent: "flex-end",
        alignItems: "flex-start",
        padding: "5%",
      }}
    >
      {/* Main Review Card */}
      <div
        style={{
          width: cardWidth,
          backgroundColor: cardBackgroundColor,
          borderRadius: 24,
          boxShadow: "0 24px 48px rgba(0,0,0,0.15), 0 8px 16px rgba(0,0,0,0.1)",
          display: "flex",
          flexDirection: "column",
          position: "relative",
          overflow: "hidden",
          opacity: cardOpacity,
          transform: `translateY(${cardTranslateY}px) scale(${cardScale})`,
          transformOrigin: "bottom left",
        }}
      >
        {/* Google-style Multi-color Top Border */}
        <div
          style={{
            height: 8,
            width: "100%",
            background: `linear-gradient(90deg, ${googleBlue} 25%, ${googleRed} 25% 50%, ${googleYellow} 50% 75%, ${googleGreen} 75%)`,
          }}
        />

        <div
          style={{
            padding: cardPadding,
            display: "flex",
            flexDirection: "row",
            gap: 40,
            alignItems: "center",
          }}
        >
          {/* Avatar Section */}
          <div
            style={{
              width: avatarSize,
              height: avatarSize,
              borderRadius: "50%",
              overflow: "hidden",
              flexShrink: 0,
              backgroundColor: "#f0f0f0",
              boxShadow: "0 4px 12px rgba(0,0,0,0.1)",
              transform: `scale(${interpolate(cardEntrance, [0, 0.8, 1], [0, 1.1, 1], {
                extrapolateRight: "clamp",
              })})`,
            }}
          >
            {avatarImg && (
              <Img
                src={avatarImg}
                style={{
                  width: "100%",
                  height: "100%",
                  objectFit: "cover",
                }}
              />
            )}
          </div>

          {/* Content Section */}
          <div style={{ display: "flex", flexDirection: "column", gap: 16, flex: 1 }}>
            
            {/* Header: Name and Date/Subtitle */}
            <div style={{ display: "flex", flexDirection: "column", gap: 4 }}>
              <div
                style={{
                  fontSize: 36,
                  fontWeight: 700,
                  color: textColor,
                  letterSpacing: "-0.02em",
                  lineHeight: 1.1,
                  opacity: interpolate(frame, [10, 25], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" }),
                  transform: `translateY(${interpolate(frame, [10, 25], [20, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" })}px)`,
                }}
              >
                {reviewerName}
              </div>
              <div
                style={{
                  fontSize: 22,
                  fontWeight: 400,
                  color: subTextColor,
                  opacity: interpolate(frame, [15, 30], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" }),
                }}
              >
                Local Guide
              </div>
            </div>

            {/* Star Rating */}
            <div style={{ display: "flex", flexDirection: "row", gap: 8 }}>
              {[...Array(5)].map((_, index) => {
                const isFilled = index < rating;
                const starDelay = 20 + index * 4;
                const starPop = spring({
                  fps,
                  frame: frame - starDelay,
                  config: { damping: 12, stiffness: 150 },
                });
                
                // Only render partial if the rating is fractional. 
                // For simplicity, we are using full integer math or opacity tricks,
                // but standard SVG stars with full/empty logic works best for pure visuals.
                const fillOpacity = isFilled ? 1 : 0.2;

                return (
                  <div
                    key={index}
                    style={{
                      width: 32,
                      height: 32,
                      transform: `scale(${starPop})`,
                      opacity: interpolate(frame - starDelay, [0, 5], [0, 1], { extrapolateLeft: "clamp" }),
                    }}
                  >
                    <svg
                      viewBox="0 0 24 24"
                      fill={isFilled ? starColor : subTextColor}
                      style={{ opacity: fillOpacity, width: "100%", height: "100%" }}
                    >
                      <path d="M12 17.27L18.18 21l-1.64-7.03L22 9.24l-7.19-.61L12 2 9.19 8.63 2 9.24l5.46 4.73L5.82 21z" />
                    </svg>
                  </div>
                );
              })}
            </div>

            {/* Review Text */}
            <div
              style={{
                fontSize: 28,
                fontWeight: 400,
                color: textColor,
                lineHeight: 1.5,
                opacity: interpolate(frame, [35, 50], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" }),
                transform: `translateY(${interpolate(frame, [35, 50], [15, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" })}px)`,
                marginTop: 8,
              }}
            >
              "{reviewText}"
            </div>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default GoogleReviewOverlay;